effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   /////////////////////////

   float Hash( vec2 p)
    {
    	vec3 p2 = vec3(p.xy,1.0);
        return fract(sin(dot(p2,vec3(37.1,61.7, 12.4)))*3758.5453123);
    }

    float noise(in vec2 p)
    {
        vec2 i = floor(p);
    	vec2 f = fract(p);
    	f *= f * (3.0-2.0*f);

        return mix(mix(Hash(i + vec2(0.,0.)), Hash(i + vec2(1.,0.)),f.x),
    		mix(Hash(i + vec2(0.,1.)), Hash(i + vec2(1.,1.)),f.x),
    		f.y);
    }

    float fbm(vec2 p) 
    {
    	float v = 0.0;
    	v += noise(p*1.)*.5;
    	v += noise(p*2.)*.25;
    	v += noise(p*4.)*.125;
    	v += noise(p*8.)*.0625;
    	v += noise(p*16.)*.03125;
    	return v;
    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        // vec4 glow = texture2DCv(edge.texture, acScreenNorm);
        /////////////////////////


    	vec4 result;

    	vec2 uv = acScreenNorm;
        vec2 uvDisplace = uv;

        bool apply = true;

    	float factor = (1.-(0.14+progressa));
        if(!apply)
            factor = 0.0;

        float factorInv = 1.0 - factor;


    	// burn
        vec2 p = uv * 10.;
        //float noiseBurn = noise(uv + noise(uv * 2. +  fbm(uv * 40.)));

        float noiseControl = noise(uv * 3. + 2.5)*1.3;

        float noiseBurn = fbm(uv * 15. );
        //noiseBurn *= noiseControl;

    	float burn = (noiseBurn + factor);
        if(apply)
        	burn = pow(burn, feather);
        burn = clamp(burn, 0.0, 1.0);


        float displace = -mix(0.0, burn * 0.03, factor);
        uvDisplace += displace;

        vec3 src = vec3(color.rgb);
    	vec3 tgt = texture2DCv(inputImg.texture, uv).rgb;
    	vec3 col = src;


        col = vec3(burn);
        if(apply)
        col = mix(src, tgt, burn);
    	result = vec4(col, 1.0);

    	vec4 factorx = result * alpha;
        factorx *= texColor.a;
        vec4 resultfinal = factorx + (texColor*(1.0-factorx.a));

    	gl_FragColor = resultfinal;
    	// gl_FragColor = mix(resultfinal,chromakey,1.0) * texColor.a;
    }
